                </span>
            </Tooltip>
            <Tooltip title="Move entry down">
                <span>
                    <IconButton
                        aria-label={`Move ${semanticLabel(entryKey)} down`}
                        disabled={entryIndex === entryCount - 1}
                        onClick={() => session.moveLegendEntry(entryKey, entryIndex + 1)}
                        size="small"
                    >
                        <ArrowDownwardOutlined fontSize="small" />
